package kz.zeroops.agent;
import java.time.Instant; import java.util.Set; import org.springframework.stereotype.Component;
/** Rejects any execution input outside the signed-manifest allowlist. */
@Component public class AgentBoundary { private static final Set<String> RUNTIMES=Set.of("NODE","SPRING_BOOT","PYTHON","GO","DOTNET","DOCKERFILE"); private static final String GITHUB_REPOSITORY="(?:https://github\\.com/|git@github\\.com:)[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:\\.git)?/?"; private static final String REVISION="(?:[A-Fa-f0-9]{7,64}|manual-[0-9]+)"; public boolean accepts(Manifest m){return m!=null&&RUNTIMES.contains(m.runtime())&&m.expiresAt().isAfter(Instant.now())&&m.repositoryUrl().matches(GITHUB_REPOSITORY)&&m.branch().matches("[A-Za-z0-9._/-]{1,255}")&&m.commitSha().matches(REVISION)&&m.healthPath().matches("/[A-Za-z0-9._~/%?-]{0,255}")&&m.servicePath().matches("(?:\\.|[A-Za-z0-9._/-]{1,200})")&&!m.servicePath().contains("..")&&m.applicationPort()>0&&m.applicationPort()<65536&&(m.publicPort()==0||(m.publicPort()>=18100&&m.publicPort()<=18999))&&m.imageTag().matches("[a-z0-9._/-]+:"+REVISION)&&!m.rawCommand();} public record Manifest(String deploymentId,String projectId,String serverId,String repositoryUrl,String branch,String commitSha,String runtime,int applicationPort,int publicPort,String healthPath,String servicePath,String imageTag,Instant expiresAt,boolean rawCommand){} }
